import {controller, target} from '@github/catalyst'
import {isFeatureEnabled} from '@github-ui/feature-flags'

const ANIMATION_DURATION = 200
const AT_COPILOT_VALUE = '@copilot'

const CHECKMARK_PATH =
  'M13.78 4.22a.75.75 0 010 1.06l-7.25 7.25a.75.75 0 01-1.06 0L2.22 9.28a.75.75 0 011.06-1.06L6 10.94l6.72-6.72a.75.75 0 011.06 0z'

const STYLES = {
  checkmarkContainer: 'width: 16px; flex-shrink: 0; display: flex; align-items: center; justify-content: center;',
  avatarIcon:
    'flex-shrink: 0; border-radius: 4px; box-shadow: 0 0 0 1px var(--borderColor-default, rgba(31,35,40,0.15)); display: inline-block; vertical-align: middle; overflow: hidden;',
} as const

type AnimationState = {visible: boolean; timer?: number}

export interface ModelOption {
  id: string
  name: string
  icon?: string
  multiplier?: number
}

interface ModelsResponse {
  models: ModelOption[]
  current_model?: string
}

@controller('copilot-mentions-hint')
export class CopilotMentionsHintElement extends HTMLElement {
  @target declare inputField: HTMLInputElement | HTMLTextAreaElement
  @target declare indicator: HTMLElement
  @target declare infoText: HTMLElement
  @target declare button: HTMLButtonElement
  @target declare submitButton: HTMLButtonElement
  @target declare hintMessage: HTMLElement

  @target declare modelSelect: HTMLSelectElement
  @target declare modelAutocomplete: HTMLElement
  @target declare modelPickerBadge: HTMLButtonElement
  @target declare modelPickerIcon: HTMLElement
  @target declare modelPickerName: HTMLElement
  @target declare modelPickerMenu: HTMLElement

  #animState: AnimationState = {visible: false}
  #selectedModel = 'auto'
  #models: ModelOption[] = []
  #modelsLoaded = false
  #modelsLoading = false
  #originalSubmitText = ''
  #cachedCopilotIcon: SVGSVGElement | null = null

  #abortController: AbortController | null = null

  get #isModelPickerEnabled(): boolean {
    return (
      isFeatureEnabled('copilot_swe_agent_pr_comment_model_picker') && this.hasAttribute('data-model-picker-enabled')
    )
  }

  get #escapedCopilotValue(): string {
    return AT_COPILOT_VALUE.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')
  }

  connectedCallback() {
    if (!this.inputField) return

    this.#abortController = new AbortController()
    const {signal} = this.#abortController

    if (this.submitButton) {
      this.#originalSubmitText = this.submitButton.textContent || 'Comment'
    }

    if (this.infoText) {
      this.#animState = {visible: !this.infoText.classList.contains('sr-only')}
    }

    const inputEvents = ['input', 'change', 'click', 'keyup', 'select'] as const
    for (const event of inputEvents) {
      this.inputField.addEventListener(event, this.#updateIndicator, {signal})
    }
    this.inputField.addEventListener('keydown', this.#handleKeyDown as EventListener, {signal})

    this.button?.addEventListener('click', this.#toggleInfoText, {signal})

    const form = this.inputField.closest('form')
    form?.addEventListener('reset', this.#handleFormReset, {signal})
    form?.addEventListener('submit', this.#handleFormSubmit, {signal})

    if (this.#isModelPickerEnabled) {
      // Cache the server-rendered Primer octicon so we can reuse it
      // instead of hardcoding SVG paths that may drift out of sync.
      if (this.modelPickerIcon instanceof SVGSVGElement) {
        this.#cachedCopilotIcon = this.modelPickerIcon.cloneNode(true) as SVGSVGElement
      }
      this.modelSelect?.addEventListener('change', this.#handleModelChange, {signal})
      this.modelAutocomplete?.addEventListener('click', this.#handleDropdownClick, {signal})
      this.modelPickerMenu?.addEventListener('toggle', this.#handleMenuToggle, {signal})
    }

    this.button?.setAttribute('aria-expanded', 'false')
    this.#updateIndicator()
  }

  disconnectedCallback() {
    this.#abortController?.abort()
    this.#abortController = null

    if (this.#animState.timer) {
      clearTimeout(this.#animState.timer)
    }
  }

  #hasCopilotMention(text: string): boolean {
    const pattern = `(?:^|[^A-Za-z0-9])${this.#escapedCopilotValue}(?:\\+[A-Za-z0-9.-]+)?(?:[^A-Za-z0-9+]|$)`
    return new RegExp(pattern, 'i').test(text)
  }

  #isCaretInMention(text: string, caret: number): boolean {
    const re = new RegExp(`(?:^|[^a-zA-Z0-9])(${this.#escapedCopilotValue}(?:\\+[A-Za-z0-9.-]+)?\\s?)`, 'gi')

    for (let m: RegExpExecArray | null; (m = re.exec(text)); ) {
      const mention = m[1]
      if (!mention) continue
      const start = m.index + (m[0].length - mention.length)
      const end = start + mention.length
      if (caret >= start && caret <= end) return true
    }
    return false
  }

  #updateIndicator = () => {
    if (!this.inputField) return

    const text = this.inputField.value
    const hasCopilot = this.#hasCopilotMention(text)

    if (!hasCopilot) {
      this.#handleNoCopilotMention()
      return
    }

    this.#handleCopilotMentionPresent(text)
  }

  #handleNoCopilotMention() {
    if (this.indicator) this.indicator.hidden = true

    if (this.infoText) {
      this.infoText.hidden = true
      this.infoText.classList.remove('sr-only')
    }
    this.#animState = {visible: false}

    if (this.button) {
      this.button.classList.remove('is-expanded')
      this.button.style.backgroundColor = ''
      this.button.setAttribute('aria-expanded', 'false')
    }

    this.#resetModelSelection()
    this.#hideModelPickerBadge()
    this.#showHintMessage()
    this.#updateSubmitButton(false)
  }

  #handleCopilotMentionPresent(text: string) {
    if (this.#isModelPickerEnabled) {
      this.#showModelPickerBadge()
      this.#hideHintMessage()
      this.#updateSubmitButton(true)

      if (!this.#modelsLoaded && !this.#modelsLoading) {
        void this.#fetchModels()
      }
    }

    if (this.indicator) this.indicator.hidden = false

    if (this.infoText && !this.#isModelPickerEnabled) {
      this.infoText.hidden = false
    }

    if (this.infoText && this.button && !this.#isModelPickerEnabled) {
      const caret = this.inputField.selectionStart ?? 0
      const shouldShow = this.#isCaretInMention(text, caret)

      if (!shouldShow && !this.#animState.visible) {
        this.infoText.classList.add('sr-only')
      }

      this.#animateInfoText(shouldShow)
      this.button.classList.toggle('is-expanded', shouldShow)
      this.button.style.backgroundColor = shouldShow ? 'var(--bgColor-muted)' : ''
      this.button.setAttribute('aria-expanded', shouldShow ? 'true' : 'false')
    }
  }

  #showHintMessage() {
    if (this.hintMessage) {
      this.hintMessage.hidden = false
    }
  }

  #hideHintMessage() {
    if (this.hintMessage) {
      this.hintMessage.hidden = true
    }
  }

  #showModelPickerBadge() {
    if (!this.modelPickerBadge) return

    this.modelPickerBadge.hidden = false
    this.#updateModelPickerBadgeDisplay()

    if (this.infoText) this.infoText.hidden = true
    if (this.button) this.button.hidden = true
  }

  #hideModelPickerBadge() {
    if (!this.modelPickerBadge) return

    this.modelPickerBadge.hidden = true
    if (this.button) this.button.hidden = false
  }

  #sanitizeIconUrl(icon: string | null | undefined): string {
    if (!icon) return ''

    try {
      const url = new URL(icon, window.location.origin)
      if (url.protocol === 'http:' || url.protocol === 'https:') {
        return url.href
      }
    } catch {
      // Invalid URL
    }

    return ''
  }

  #updateModelPickerBadgeDisplay() {
    const model = this.#getSelectedModelInfo()
    const currentIcon = this.modelPickerIcon

    if (currentIcon) {
      const newIcon =
        model.id === 'auto' || !model.icon ? this.#createCopilotOcticon(16) : this.#createAvatarIcon(model.icon, 16)
      newIcon.setAttribute('data-target', 'copilot-mentions-hint.modelPickerIcon')
      currentIcon.replaceWith(newIcon)
    }

    if (this.modelPickerName) {
      this.modelPickerName.textContent = model.name
    }
  }

  #getSelectedModelInfo(): ModelOption {
    const model = this.#models.find(m => m.id === this.#selectedModel)
    if (model && model.id !== 'auto') return model

    const listContainer = this.modelAutocomplete
    const staticItem = listContainer?.querySelector(`[data-model-id="${this.#selectedModel}"]`)
    if (staticItem) {
      return {
        id: this.#selectedModel,
        name: staticItem.getAttribute('data-model-name') || this.#selectedModel,
        icon: this.#sanitizeIconUrl(staticItem.getAttribute('data-model-icon')),
      }
    }

    return {id: 'auto', name: 'Auto'}
  }

  #handleMenuToggle = (event: Event) => {
    const toggleEvent = event as ToggleEvent
    if (toggleEvent.newState === 'open') {
      if (!this.#modelsLoaded && !this.#modelsLoading) {
        void this.#fetchModels()
      }
      this.#renderModels()
    }
  }

  #updateSubmitButton(isCopilotMode: boolean) {
    if (!this.submitButton) return
    this.submitButton.textContent = isCopilotMode ? 'Start new session' : this.#originalSubmitText || 'Comment'
  }

  async #fetchModels() {
    const modelsUrl = this.getAttribute('data-models-url') || this.modelAutocomplete?.getAttribute('data-models-url')

    if (!modelsUrl) {
      this.#modelsLoaded = true
      return
    }

    this.#modelsLoading = true

    try {
      const response = await fetch(modelsUrl, {
        headers: {
          Accept: 'application/json',
          'X-Requested-With': 'XMLHttpRequest',
        },
      })

      if (!response.ok) {
        throw new Error(`Failed to fetch models: ${response.status}`)
      }

      const data: ModelsResponse = await response.json()
      this.#models = data.models

      if (data.current_model && this.#selectedModel === 'auto') {
        this.#selectedModel = data.current_model
        this.#updateModelPickerBadgeDisplay()
      }

      this.#renderModels()
      this.#modelsLoaded = true
    } catch (error) {
      // eslint-disable-next-line no-console
      console.error('Failed to fetch coding agent models:', error)
      this.#modelsLoaded = true
    } finally {
      this.#modelsLoading = false
    }
  }

  #renderModels() {
    const listContainer = this.modelAutocomplete
    if (!listContainer) return

    const actionList = listContainer.querySelector('ul[role="menu"]') || listContainer

    const existingItems = actionList.querySelectorAll('[role="menuitemradio"]')
    for (const item of existingItems) {
      item.remove()
    }

    const autoModel: ModelOption = {id: 'auto', name: 'Auto', multiplier: 1}
    const modelsToRender = [autoModel, ...this.#models.filter(m => m.id !== 'auto')]

    for (const model of modelsToRender) {
      actionList.appendChild(this.#createModelItem(model))
    }
  }

  #createModelItem(model: ModelOption): HTMLElement {
    const isSelected = model.id === this.#selectedModel
    const item = document.createElement('li')

    item.setAttribute('role', 'menuitemradio')
    item.setAttribute('data-model-id', model.id)
    item.setAttribute('data-model-name', model.name)
    item.setAttribute('tabindex', '-1')
    if (model.icon) item.setAttribute('data-model-icon', model.icon)
    item.setAttribute('aria-checked', isSelected ? 'true' : 'false')

    item.className = 'ActionListItem'
    item.style.cssText =
      'padding: 6px 10px; cursor: pointer; display: flex; align-items: center; gap: 8px; border-radius: 6px; font-size: 12px;'

    item.appendChild(this.#createCheckmark(isSelected))

    if (model.id === 'auto') {
      item.appendChild(this.#createCopilotOcticon(16))
    } else if (model.icon) {
      item.appendChild(this.#createAvatarIcon(model.icon, 16))
    }

    item.appendChild(this.#createModelLabel(model.name))

    if (model.multiplier !== undefined) {
      const badge = document.createElement('span')
      badge.style.cssText =
        'font-size: 11px; padding: 1px 4px; color: var(--fgColor-muted); background: transparent; margin-left: auto;'
      badge.textContent = `${Number(model.multiplier.toFixed(2))}x`
      item.appendChild(badge)
    }

    item.addEventListener('keydown', (event: KeyboardEvent) => {
      // eslint-disable-next-line @github-ui/ui-commands/no-manual-shortcut-logic
      if (event.key === 'Enter' || event.key === ' ') {
        event.preventDefault()
        this.#selectModel(model.id)
      }
    })

    return item
  }

  #createCheckmark(isSelected: boolean): HTMLElement {
    const container = document.createElement('span')
    container.style.cssText = STYLES.checkmarkContainer

    if (isSelected) {
      const svg = document.createElementNS('http://www.w3.org/2000/svg', 'svg')
      svg.setAttribute('width', '16')
      svg.setAttribute('height', '16')
      svg.setAttribute('viewBox', '0 0 16 16')
      svg.setAttribute('fill', 'currentColor')
      svg.style.color = 'var(--fgColor-muted)'

      const path = document.createElementNS('http://www.w3.org/2000/svg', 'path')
      path.setAttribute('fill-rule', 'evenodd')
      path.setAttribute('d', CHECKMARK_PATH)
      svg.appendChild(path)
      container.appendChild(svg)
    }

    return container
  }

  #createCopilotOcticon(size: number): SVGSVGElement {
    if (this.#cachedCopilotIcon) {
      const clone = this.#cachedCopilotIcon.cloneNode(true) as SVGSVGElement
      clone.setAttribute('width', String(size))
      clone.setAttribute('height', String(size))
      clone.style.cssText = 'flex-shrink: 0;'
      return clone
    }

    // Fallback: create a minimal empty SVG if the server-rendered icon was not available
    const svg = document.createElementNS('http://www.w3.org/2000/svg', 'svg')
    svg.setAttribute('width', String(size))
    svg.setAttribute('height', String(size))
    svg.setAttribute('viewBox', '0 0 16 16')
    svg.setAttribute('fill', 'currentColor')
    svg.setAttribute('aria-hidden', 'true')
    svg.style.cssText = 'flex-shrink: 0;'
    return svg
  }

  #createAvatarIcon(iconUrl: string, size: number): HTMLElement {
    const icon = document.createElement('img')
    icon.src = this.#sanitizeIconUrl(iconUrl)
    icon.alt = ''
    icon.width = size
    icon.height = size
    icon.style.cssText = STYLES.avatarIcon
    return icon
  }

  #createModelLabel(name: string): HTMLElement {
    const label = document.createElement('span')
    label.className = 'ActionListItem-label'
    label.textContent = name
    return label
  }

  #resetModelSelection() {
    this.#selectedModel = 'auto'
    if (this.modelSelect) this.modelSelect.value = 'auto'
    this.#updateModelPickerBadgeDisplay()
  }

  #selectModel(modelId: string) {
    this.#selectedModel = modelId
    this.#renderModels()
    this.#updateModelPickerBadgeDisplay()
    if (this.modelSelect) this.modelSelect.value = modelId

    // Close the ActionMenu overlay
    const overlay = this.modelAutocomplete
    if (overlay && typeof overlay.hidePopover === 'function') {
      try {
        overlay.hidePopover()
      } catch (e) {
        if (!(e instanceof DOMException)) throw e
      }
    }

    this.inputField.focus()
  }

  #handleKeyDown = (_event: KeyboardEvent) => {}

  #handleDropdownClick = (event: Event) => {
    const eventTarget = event.target as HTMLElement
    const item = eventTarget.closest('[data-model-id]')
    if (item) {
      const modelId = item.getAttribute('data-model-id')
      if (modelId) {
        this.#selectModel(modelId)
      }
    }
  }

  #toggleInfoText = (event: Event) => {
    if (!this.button) return

    event.preventDefault()
    event.stopPropagation()

    const nextVisible = !this.#animState.visible
    this.#animateInfoText(nextVisible)
    this.button.classList.toggle('is-expanded', nextVisible)
    this.button.style.backgroundColor = nextVisible ? 'var(--bgColor-muted)' : ''
    this.button.setAttribute('aria-expanded', nextVisible ? 'true' : 'false')
  }

  #handleFormReset = () => {
    setTimeout(() => {
      this.#selectedModel = 'auto'
      if (this.modelSelect) {
        this.modelSelect.value = 'auto'
      }
      this.#updateIndicator()
    }, 0)
  }

  #animateInfoText(makeVisible: boolean) {
    if (!this.infoText) return
    if (this.#animState.visible === makeVisible) return

    if (this.#animState.timer) {
      clearTimeout(this.#animState.timer)
      this.#animState.timer = undefined
    }

    // Keep in layout during animations
    this.infoText.hidden = false

    if (makeVisible) {
      this.infoText.classList.remove('sr-only')

      this.infoText.style.transition = 'none'
      this.infoText.style.transform = 'translateX(-5px)'
      void this.infoText.offsetWidth // force reflow

      this.infoText.style.transition = `transform ${ANIMATION_DURATION}ms ease-out`
      this.infoText.style.transform = 'translateX(0)'

      this.#animState.visible = true
    } else {
      this.infoText.style.transition = `transform ${ANIMATION_DURATION}ms ease-in`
      this.infoText.style.transform = 'translateX(-5px)'

      this.#animState.visible = false
      this.#animState.timer = window.setTimeout(() => {
        if (!this.infoText) return
        this.infoText.classList.add('sr-only')
        this.#animState.timer = undefined
      }, ANIMATION_DURATION)
    }
  }

  // === Event Handlers ===
  #handleModelChange = (event: Event) => {
    const select = event.target as HTMLSelectElement
    this.#selectedModel = select.value
    this.#updateModelPickerBadgeDisplay()
  }

  #handleFormSubmit = () => {
    if (!this.inputField || !this.#isModelPickerEnabled) return
    if (this.#selectedModel === 'auto' || this.#selectedModel === '') return

    const text = this.inputField.value

    const mentionPattern = new RegExp(
      `((?:^|[^A-Za-z0-9]))(${this.#escapedCopilotValue})(?![+])(?=[^A-Za-z0-9]|$)`,
      'gi',
    )
    const updatedText = text.replace(mentionPattern, `$1${AT_COPILOT_VALUE}+${this.#selectedModel}`)

    if (updatedText !== text) {
      this.inputField.value = updatedText
    }
  }
}
